def forward(groups):
    date_part = groups[0]  # S0
    space_part = groups[1]  # Space
    time_part = groups[2]  # S1
    dt = datetime.strptime(date_part + time_part, '%y%m%d%H%M%S')
    spaces = len(space_part)
    return {'stored': [int(dt.timestamp() * 1000)], 'layout': [spaces]}

def inverse(record):
    millis = int(record['stored'][0])
    spaces = record['layout'][0]
    dt = datetime.fromtimestamp(millis / 1000)
    return dt.strftime('%y%m%d' + (' ' * spaces) + '%H%M%S')
